package flexcluster_test

import (
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/resource"

	"github.com/mongodb/terraform-provider-mongodbatlas/internal/testutil/acc"
	"github.com/mongodb/terraform-provider-mongodbatlas/internal/testutil/mig"
)

// Migration tests for the autogenerated mongodbatlas_flex_cluster (no-change group): the config
// syntax is identical under the manual and autogen implementations, so the migration must plan
// EMPTY at the same address: no accepted diffs, no replacement.

const migResourceName = "mongodbatlas_flex_cluster.test"

// TestMigFlexCluster_basic covers the case without tags: the manual implementation stores null
// tags when Atlas returns an empty list, the autogen one must not plan a diff for it.
func TestMigFlexCluster_basic(t *testing.T) {
	migTestCase(t, false)
}

func TestMigFlexCluster_withTags(t *testing.T) {
	migTestCase(t, true)
}

func migTestCase(t *testing.T, withTags bool) {
	t.Helper()
	var (
		projectID   = acc.ProjectIDExecution(t)
		clusterName = acc.RandomName()
		config      = migConfig(projectID, clusterName, withTags)
	)
	checks := []resource.TestCheckFunc{
		acc.CheckExistsFlexCluster(),
		resource.TestCheckResourceAttr(migResourceName, "project_id", projectID),
		resource.TestCheckResourceAttr(migResourceName, "name", clusterName),
		resource.TestCheckResourceAttr(migResourceName, "provider_settings.backing_provider_name", "AWS"),
		resource.TestCheckResourceAttr(migResourceName, "provider_settings.region_name", "US_EAST_1"),
		resource.TestCheckResourceAttrSet(migResourceName, "id"),
	}
	if withTags {
		checks = append(checks, resource.TestCheckResourceAttr(migResourceName, "tags.testKey", "testValue"))
	} else {
		checks = append(checks, resource.TestCheckNoResourceAttr(migResourceName, "tags"))
	}

	resource.ParallelTest(t, resource.TestCase{
		PreCheck:     func() { mig.PreCheckBasic(t) },
		CheckDestroy: acc.CheckDestroyFlexCluster,
		Steps: []resource.TestStep{
			{
				// Step 1: the released provider (manual implementation) creates the flex cluster.
				ExternalProviders: mig.ExternalProviders(),
				Config:            config,
				Check:             resource.ComposeAggregateTestCheckFunc(checks...),
			},
			{
				// Step 2: the autogen implementation must plan no diff at the same address.
				Config:                   config,
				ProtoV6ProviderFactories: acc.TestAccProviderV6Factories,
				PlanOnly:                 true,
				ExpectNonEmptyPlan:       false,
			},
		},
	})
}

func migConfig(projectID, clusterName string, withTags bool) string {
	tags := ""
	if withTags {
		tags = `
			tags = {
				testKey = "testValue"
			}`
	}
	return fmt.Sprintf(`
		resource "mongodbatlas_flex_cluster" "test" {
			project_id = %[1]q
			name       = %[2]q
			provider_settings = {
				backing_provider_name = "AWS"
				region_name           = "US_EAST_1"
			}
			%[3]s
		}
	`, projectID, clusterName, tags)
}
